//! The compiled tokenizer (`bpe`) versus `tokenizers`: same ids on every text, and how long
//! each one takes to load and to tokenize.
//!
//! `cargo run --release --example bpe_equal -- <compact model folder> <textos.json>`
//! (`textos.json`: an object with lists of texts; generated by the review's `motor/py/textos.py`).

use omoikane::bpe::{Bpe, FILE, compile};
use std::time::Instant;

fn main() -> anyhow::Result<()> {
    let a: Vec<String> = std::env::args().skip(1).collect();
    let dir = std::path::Path::new(&a[0]);
    let json = dir.join("tokenizer.json");
    let groups: serde_json::Map<String, serde_json::Value> = serde_json::from_slice(&std::fs::read(&a[1])?)?;

    let t = Instant::now();
    let mut hf = tokenizers::Tokenizer::from_file(&json).map_err(|e| anyhow::anyhow!("{e}"))?;
    hf.with_truncation(Some(tokenizers::TruncationParams { max_length: 2048, ..Default::default() })).map_err(|e| anyhow::anyhow!("{e}"))?;
    let hf_load = t.elapsed();
    let dest = dir.join(FILE);
    let t = Instant::now();
    compile(&json, &dest)?;
    let compile_t = t.elapsed();
    let mut open_ms = Vec::new();
    let mut bpe = None;
    for _ in 0..5 {
        let t = Instant::now();
        bpe = Some(Bpe::open(&json, &dest)?);
        open_ms.push(t.elapsed().as_secs_f64() * 1000.0);
    }
    let bpe = bpe.unwrap();
    println!("cargar tokenizer.json: {:.0} ms; compilar: {:.0} ms; abrir el compilado: {:?} ms; {} bytes", hf_load.as_secs_f64() * 1000.0, compile_t.as_secs_f64() * 1000.0, open_ms, std::fs::metadata(&dest)?.len());

    let (mut total, mut different, mut toks) = (0, 0, 0usize);
    let (mut ms_hf, mut ms_bpe) = (0.0, 0.0);
    for (g, v) in &groups {
        let (mut n, mut bad) = (0, 0);
        for t in v.as_array().unwrap() {
            let t = t.as_str().unwrap();
            for prompt in ["task: search result | query: ", "title: none | text: ", ""] {
                let s = format!("{prompt}{t}");
                let i0 = Instant::now();
                let a = hf.encode(s.as_str(), true).map_err(|e| anyhow::anyhow!("{e}"))?.get_ids().to_vec();
                ms_hf += i0.elapsed().as_secs_f64() * 1000.0;
                let i0 = Instant::now();
                let b = bpe.encode(&s, 2048);
                ms_bpe += i0.elapsed().as_secs_f64() * 1000.0;
                n += 1;
                toks += a.len();
                if a != b {
                    bad += 1;
                    if bad <= 3 {
                        let p = a.iter().zip(&b).position(|(x, y)| x != y).unwrap_or(a.len().min(b.len()));
                        println!("  DISTINTO en {g}: {:?}… hf {:?} bpe {:?} (desde {p}: {:?} / {:?})", s.chars().take(60).collect::<String>(), a.len(), b.len(), &a[p..(p + 5).min(a.len())], &b[p..(p + 5).min(b.len())]);
                    }
                }
            }
        }
        println!("{g}: {n} textos, {bad} distintos");
        total += n;
        different += bad;
    }
    println!("TOTAL {total} textos ({toks} tokens), {different} distintos; tokenizar: tokenizers {ms_hf:.0} ms, compilado {ms_bpe:.0} ms");
    Ok(())
}
